"""Public-source province profile overrides. Generated by refresh script."""

from typing import Final

PUBLIC_PROVINCE_PROFILES: Final[dict[str, tuple[str, str]]] = {
    '上海市': ('上海市', '上海市，简称“沪”，别名“申”，是中华人民共和国直辖市，超大城市，世界一线城市，位于中国东部，长江入海口，北界长江，东濒东海，南临杭州湾，西接江苏省和浙江省，地处长江三角洲冲积平原，地势坦荡低平，属北亚热带季风气候，最大河流为黄浦江。'),
    '云南省': ('云南省', '云南省，简称“云”或“滇”，地处中国西南边陲，属低纬度内陆地区。'),
    '内蒙古自治区': ('内蒙古自治区', '内蒙古自治区，简称内蒙古，首府为呼和浩特，地处中国北部，东北部与黑龙江、吉林、辽宁、河北交界，南部与山西、陕西、宁夏相邻，西南部与甘肃毗连，北部与俄罗斯、蒙古接壤。'),
    '北京市': ('北京市', '北京市，简称“京”，古称燕京、北平，是中华人民共和国首都、直辖市、国家中心城市、超大城市；中共中央、国务院批复确定的中国政治中心、文化中心、国际交往中心、科技创新中心；中国历史文化名城和古都之一、世界一线城市。'),
    '台湾省': ('台湾省', '台湾省，简称“台”。台湾古称夷洲、流求、东番、小番。是中华人民共和国省级行政区，省会台北，位于中国东南沿海的大陆架上，东临太平洋，西隔台湾海峡与福建省相望；北濒东海，南接巴士海峡与菲律宾群岛相对，纵跨温带与热带。'),
    '吉林省': ('吉林省', '吉林省，简称“吉”，是中华人民共和国省级行政区，省会长春市；位于中国东北地区中部，与辽宁省、内蒙古自治区、黑龙江省相连，并与俄罗斯、朝鲜接壤，地处东北亚地理中心位置；地势由东南向西北倾斜，呈现出东南高、西北低的特征，属于温带大陆性季风气候。'),
    '四川省': ('四川省', '四川省，简称川或蜀，中华人民共和国省级行政区，省会成都市，为道教发源地之一，古蜀文明发祥地。地处长江上游，与重庆、贵州、云南、西藏、青海、甘肃和陕西7省（自治区、直辖市）接壤。'),
    '天津市': ('天津市', '天津市，简称“津”，是中华人民共和国直辖市、国家中心城市、超大城市，地处中国北部，华北平原东北部，海河流域下游，东临渤海，北依燕山，西靠首都北京市，其余均与河北省相邻，属暖温带半湿润季风性气候，四季分明。'),
    '宁夏回族自治区': ('宁夏回族自治区', '宁夏回族自治区，简称“宁”，是中华人民共和国省级行政区，首府银川市，位于中国西北地区，东邻陕西省，西部、北部接内蒙古自治区，南部与甘肃省相连。'),
    '安徽省': ('安徽省', '安徽省，简称“皖”，是中华人民共和国省级行政区，省会合肥市，位于中国华东、长江三角洲地区，东连江苏省、浙江省，西接湖北省、河南省，南邻江西省，北靠山东省，地势西南高、东北低，地形地貌南北迥异，复杂多样。地处暖温带与亚热带过渡地区，淮河以北属暖温带半湿润季风气候，淮河以南为亚热带湿润季风气候。'),
    '山东省': ('山东省', '山东省，简称“鲁”，中华人民共和国省级行政区，省会济南市，位于中国东部沿海、黄河下游，境域包括半岛和内陆两部分，山东半岛突出于渤海、黄海之中；内陆部分自北而南与河北、河南、安徽、江苏接壤。'),
    '山西省': ('山西省', '山西省，简称“晋”，省会太原市，地处黄河流域中部的黄土高原，东与河北省为邻；西、南部与陕西省、河南省相望；北与内蒙古自治区毗连。'),
    '广东省': ('广东省', '广东省，简称粤，中华人民共和国省级行政区，省会是广州市。地处中国大陆最南部，东邻福建，南临南海，西接广西，北接江西、湖南。'),
    '广西壮族自治区': ('广西壮族自治区', '广西壮族自治区，简称“桂”，中国南部的省级行政区，首府南宁市。南濒北部湾，东连广东，北接湖南，西北依贵州，西与云南接壤，西南与越南交界。'),
    '新疆维吾尔自治区': ('新疆维吾尔自治区', '新疆维吾尔自治区，简称“新”，是中华人民共和国省级行政区，首府乌鲁木齐市，位于中国西北地区。'),
    '江苏省': ('江苏省', '江苏省，简称“苏”，位于中国沿海地区中部，长江、淮河下游，东濒黄海，北接山东省，西连安徽省，东南与上海市、浙江省接壤，地形以平原为主，绝大部分地区在海拔50米以下；气候类型属于温带向亚热带的过渡性气候。'),
    '江西省': ('江西省', '江西省，简称“赣”，是中华人民共和国省级行政区，省会为南昌市，位于中国东南部，长江中下游南岸，处北纬24°29′14″至30°04′43″与东经113°34′18″至118°28′56″之间，东邻浙江省、福建省，南连广东省，西挨湖南省，北毗长江共接湖北省、安徽省，为长三角、珠三角、海峡西岸的中心腹地。'),
    '河北省': ('河北省', '河北省，简称“冀”，中华人民共和国省级行政区，省会石家庄，位于北纬36°05′-42°40′，东经113°27′-119°50′之间，地处华北，漳河以北，东临渤海、内环京津。东南部、南部衔山东、河南，西倚太行山与山西省为邻，西北与内蒙古自治区交界，东北部与辽宁接壤。海岸线长487千米。'),
    '河南省': ('河南省', '河南省，简称“豫”，中华人民共和国省级行政区，省会为郑州市，位于中国中东部、黄河中下游地区。'),
    '浙江省': ('浙江省', '浙江省，简称“浙”，是中华人民共和国省级行政区，省会杭州市。地处中国东南沿海，长江三角洲南翼，东临东海，北与上海市、江苏省接壤，南接福建省，西与安徽省、江西省相连。钱塘江为浙江省最大河流，历史上名为浙江，浙江省因此而得名。“七山一水两分田”是浙江地形的概貌，浙江省是中国岛屿最多的省份，海岸线总长居全国首位。浙江省属亚热带季风性湿润气候。'),
    '海南省': ('海南省', '海南省，简称“琼”，是中华人民共和国最南端的省级行政区，省会海口市。'),
    '湖北省': ('湖北省', '湖北省，简称“鄂”，又名“楚”，别名荆楚，中华人民共和国省级行政区，省会武汉。地处中国中部地区，长江中游，东邻安徽，西连重庆，西北与陕西接壤，南接江西、湖南，北与河南毗邻。'),
    '湖南省': ('湖南省', '湖南省，简称“湘”，中华人民共和国省级行政区。位于中国中部、长江中游。'),
    '澳门特别行政区': ('澳门特别行政区', '澳门特别行政区，简称“澳”，是直辖于中华人民共和国中央人民政府的特别行政区。位于中国南部珠江口西侧，是中国内地与南海的水陆交汇处，毗邻广东省，与香港特别行政区相距60千米，距离广东省广州市145千米。澳门特别行政区由澳门半岛和氹仔、路环二岛以及路氹城（路氹填海区）组成，下辖7个堂区。'),
    '甘肃省': ('甘肃省', '甘肃省，中华人民共和国省级行政区，简称“甘”或“陇”，省会兰州市。位于中国西北地区，东通陕西，西达新疆，南瞰四川、青海，北扼宁夏、内蒙古，西北端与蒙古接壤。'),
    '福建省': ('福建省', '福建省，简称“闽”。是著名革命老区、中华人民共和国省级行政区。省会福州市，地处中国东南沿海，东北与浙江省毗邻，西北与江西省接界，西南与广东省相连，东南隔台湾海峡与台湾省相望；全省地势西北高，东南低，呈依山傍海态势，境内山地、丘陵。'),
    '西藏自治区': ('西藏自治区', '西藏自治区，简称“藏”，是中华人民共和国五个少数民族自治区之一，位于中国西南地区，素有“世界屋脊”之称的青藏高原的西南部，地处北纬26°50′至36°53′，东经78°25′至99°06′之间，平均海拔在4000米以上。'),
    '贵州省': ('贵州省', '贵州省，简称“黔”或“贵”，中华人民共和国省级行政区，位于西南地区东南部，北接四川省和重庆市，东毗湖南省、南邻广西壮族自治区、西连云南省，地处云贵高原，境内地势西高东低，自中部向北、东、南三面倾斜。'),
    '辽宁省': ('辽宁省', '辽宁省，简称“辽”，是中华人民共和国省级行政区，省会沈阳市。辽宁省位于中国东北地区南部，陆地14.87万平方千米。'),
    '重庆市': ('重庆市', '重庆市，简称“渝”，别称山城、江城，是中华人民共和国直辖市、超大城市，国家中心城市，是复合型城市，以主城区为依托，大、中、小城市有机结合的组团式、层级式现代城市群，地处中国西南地区、长江上游，东邻湖北省、湖南省，南接贵州省，西靠四川省，北连陕西省以及四川省，地貌以山地、丘陵为主。属亚热带季风性湿润气候，长江干流在境内流程665千米。'),
    '陕西省': ('陕西省', '陕西省，简称“陕”或“秦”，中华人民共和国省级行政区，省会西安，位于中国内陆腹地，黄河中游，东邻山西、河南，西连宁夏、甘肃，南抵四川、重庆、湖北，北接内蒙古，介于东经105°29′—111°15′，北纬31°42′—39°35′之间。'),
    '青海省': ('青海省', '青海省，简称“青”，是中华人民共和国省级行政区，位于中国西部、青藏高原的东北部，下辖2个地级市、6个自治州。'),
    '香港特别行政区': ('香港特别行政区', '香港特别行政区，简称“港”，位于中国南部、珠江口以东，西与澳门隔海相望，北与深圳相邻，南临珠海万山群岛，区域范围包括香港岛、九龙、新界和周围262个岛屿。'),
    '黑龙江省': ('黑龙江省', '黑龙江省，简称黑，中华人民共和国省级行政区，省会哈尔滨市，位于中国东北部，北、东部与俄罗斯隔江相望。'),
}
